import warp as wpfrom . import collision_driverfrom . import smooth_accfrom . import smooth_actuatorfrom . import smooth_dragfrom . import smooth_muscle_actfrom . import smooth_muscle_ptfrom . import smooth_muscle_eqfrom . import smooth_muscle_fnfrom . import smooth_muscle_metabolicfrom . import smooth_frcfrom . import smooth_hunt_crossleyfrom . import smooth_inertfrom . import smooth_exponential_limitfrom . import smooth_hc_limitsfrom . import smooth_postfrom . import smooth_posfrom . import smooth_velfrom .types import ContactTypefrom .types import LimitTypefrom .types import Datafrom .types import Modelfrom .warp_util import event_scopewp.set_module_options({"enable_backward": False})@event_scopedef realize_position(m: Model, d: Data, run_reset: bool = False):    """ Position-dependent computations. """    # If we requested a reset, let's make sure we're within the joint limits    if run_reset:        smooth_pos.fix_qpos_limits(m, d)    # mobilizer transforms    smooth_pos.calc_mobilizer_X_MF(m, d)    # body world positions    smooth_pos.calc_body_transforms(m, d)    # across-joint velocity Jacobian    smooth_pos.joint_velocity_jacobian(m, d)    # COM and inertia matrices    smooth_pos.joint_independent_kinematics(m, d)    # world positions for colliders, visuals, sites    smooth_pos.attachment_kinematics(m, d)    collision_driver.collision(m, d)@event_scopedef realize_velocity(m: Model, d: Data):    """Velocity-dependent computations."""    # body velocities    smooth_vel.compute_body_velocities(m, d)    # derivative of the velocity Jacobian    smooth_vel.joint_velocity_jacobian_dot(m, d)    # body accelerations from parent to child body    smooth_vel.compute_parent_to_child_accelerations(m, d)    # gyroscopic moment, coriolis acceleration    smooth_vel.joint_independent_kinematics_vel(m, d)@event_scopedef realize_articulated_body(m: Model, d: Data):    smooth_inert.articulated_body_inertia(m, d)    smooth_inert.articulated_body_velocity(m, d)    return@event_scopedef compute_accelerations(m: Model, d: Data):    smooth_acc.calc_udot(m, d)    return@event_scopedef fwd_muscles(m: Model, d: Data, run_reset: bool):    """ Muscle-related computations. """    if not m.nmuscle:        return    # Activation dynamics    smooth_muscle_act.compute_act_dot(m, d)    # Function-path approximation vs point-based path    if wp.static(m.opt.use_fn_path):        smooth_muscle_fn.muscle_path(m, d)    else:        smooth_muscle_pt.muscle_path(m, d)    # Equilibrate on reset    if run_reset:        smooth_muscle_eq.muscle_reset(m, d)    smooth_muscle_eq.realize_muscle_state(m, d)@event_scopedef fwd_actuators(m: Model, d: Data):    """ Actuator-related computations. """    if not m.nactuator:        return    smooth_actuator.compute_act_dot(m, d)@event_scopedef realize_forces(m: Model, d: Data):    """ Force-related computations. """    smooth_frc.reset_forces(m, d)    # smooth_frc.apply_gravity(m, d)    smooth_hunt_crossley.contact_forces(m, d)    # wp.copy(d.xfrc, d.xfrc_gravity)    wp.copy(d.xfrc, d.xfrc_contact)    # smooth_frc.accumulate_forces(m, d)    # smooth_frc.reset_forces(m, d)    #    # # Inverse dynamics for bias forces    # smooth_frc.bias_force(m, d)    #    # # Spring, damping, drag    # smooth_frc.spring(m, d)    # smooth_frc.damping(m, d)    # if m.opt.enable_drag:    #     smooth_drag.drag(m, d)    #    # # Muscles    # if wp.static(m.opt.use_fn_path):    #     smooth_muscle_fn.muscle_force(m, d)    # else:    #     smooth_muscle_pt.muscle_force(m, d)    #    # # Actuators    # smooth_actuator.actuator_force(m, d)    #    # # Contact forces    # if wp.static(m.opt.contact_type == ContactType.HUNT_CROSSLEY):    #     smooth_hunt_crossley.contact_forces(m, d)    #    # # Joint limit forces    # if wp.static(m.opt.limit_type == LimitType.EXPONENTIAL):    #     smooth_exponential_limit.limit_forces(m, d)    # elif wp.static(m.opt.limit_type == LimitType.HUNT_CROSSLEY):    #     smooth_hc_limits.limit_forces(m, d)    #    # smooth_frc.accumulate_forces(m, d)@event_scopedef post(m: Model, d: Data):    """ Post-processing computations. """    smooth_post.compute_joint_moments(m, d)    smooth_muscle_metabolic.compute_muscle_metabolics(m, d)@event_scopedef fwd(m: Model, d: Data):    """Forward dynamics (i.e., realize state). No integration """    realize_position(m, d, run_reset=False)    realize_velocity(m, d)    realize_articulated_body(m, d)    realize_forces(m, d)    compute_accelerations(m, d)    # fwd_forces(m, d)    # fwd_muscles(m, d, run_reset=False)    # fwd_actuators(m, d)    # fwd_acceleration(m, d)@event_scopedef reset(m: Model, d: Data):    """ Called after resetting any of the worlds, realize state """    realize_position(m, d, run_reset=True)    # fwd_velocity(m, d)    # fwd_muscles(m, d, run_reset=True)  # equilibrate the muscles    # fwd_actuators(m, d)    # fwd_forces(m, d)    # fwd_acceleration(m, d)    # post(m, d)    # d.world_reset.zero_()@event_scopedef fk(m: Model, d: Data):    """ Forward kinematics only for position-dependent quantities """    realize_position(m, d)